import React, { useEffect, useState } from 'react';

type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
    bgColor?: string;       // background color
    hoverBgColor?: string;  // background color on hover
    textColor?: string;
    clearStyle?: boolean;   // if true, removes all styles
    textHover?: boolean;    // if true, changes text color on hover
};

function adjustColorBrightness(hex: string, amount: number): string {
    if (hex === 'none') return hex; // Treat 'none' as no color change
    const col = hex.replace('#', '');
    const num = parseInt(col, 16);
    let r = (num >> 16) + amount;``
    let g = ((num >> 8) & 0x00ff) + amount;
    let b = (num & 0x0000ff) + amount;

    r = Math.max(Math.min(255, r), 0);
    g = Math.max(Math.min(255, g), 0);
    b = Math.max(Math.min(255, b), 0);

    return `#${(r << 16 | g << 8 | b).toString(16).padStart(6, '0')}`;
}

function isDarkColor(hex: string): boolean {
    if (hex === 'none') return false; // Treat 'none' as light color
    const col = hex.replace('#', '');
    const r = parseInt(col.substring(0, 2), 16);
    const g = parseInt(col.substring(2, 4), 16);
    const b = parseInt(col.substring(4, 6), 16);
    const brightness = (r * 299 + g * 587 + b * 114) / 1000;
    return brightness < 128;
}

export const Button = ({
    bgColor,
    hoverBgColor,
    textColor,
    clearStyle,
    textHover,
    className = '',
    style,
    ...props
}: ButtonProps) => {
    const [finalTextColor, setFinalTextColor] = useState<string>(textColor ?? '#000000');

    useEffect(() => {
        if (!textColor) {
            const prefersDark = window.matchMedia?.('(prefers-color-scheme: dark)').matches;
            setFinalTextColor(prefersDark ? '#ffffff' : '#000000');
        }
    }, [textColor]);

    const defaultButtonStyles: React.CSSProperties = {
        padding: !clearStyle ? '0.5rem 1rem' : undefined,
        borderRadius: !clearStyle ? '0.75rem' : undefined,
        color: !clearStyle ? '#ffffff' : undefined,
        fontWeight: !clearStyle ? 500 : undefined,
        transition: 'all 0.2s ease',
        cursor: 'pointer',
    };

    const finalBgColor = bgColor ?? (clearStyle ? 'none' : '#3b82f6');
    const autoHoverBg = adjustColorBrightness(finalBgColor, isDarkColor(finalBgColor) ? 30 : -30);
    const autoHoverText = adjustColorBrightness(finalTextColor, isDarkColor(finalTextColor) ? 30 : -30);

    const finalStyle: React.CSSProperties = {
        ...defaultButtonStyles,
        backgroundColor: finalBgColor,
        color: finalTextColor,
        ...style,
    };

    return (
        <button
            className={className}
            style={finalStyle}
            onMouseEnter={(e) => {
                const el = e.target as HTMLButtonElement;
                el.style.backgroundColor = hoverBgColor ?? autoHoverBg;
                if (textHover) el.style.color = autoHoverText;
            }}
            onMouseLeave={(e) => {
                const el = e.target as HTMLButtonElement;
                el.style.backgroundColor = finalBgColor;
                if (textHover) el.style.color = finalTextColor;
            }}
            {...props}
        />
    );
};
